FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 033: sheet metal form patterns. Generated by tools/fixtures/gen-batch-033.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function bodyCounts(context is Context) returns map
{
    const all = qEverything(EntityType.BODY);
    return { "solids" : evaluateQueryCount(context, qBodyType(all, BodyType.SOLID)),
             "active" : evaluateQueryCount(context, qActiveSheetMetalFilter(all, ActiveSheetMetal.YES)) };
}

// A form tool: a boss 5 mm in radius standing 2 mm proud of the sheet, its coordinate system on the sheet's face. The
// positive part runs down through the sheet (form tools must overlap it).
const bossTool = function(configuration is map) returns Context
{
    const context = newContextWithDefaults();
    const thickness = configuration.thickness == undefined ? 2 * millimeter : configuration.thickness;
    fCylinder(context, makeId("positive"), { "bottomCenter" : vector(0, 0, 0) * meter - vector(0, 0, 1) * thickness,
                                             "topCenter" : vector(0, 0, 2) * millimeter, "radius" : 5 * millimeter });
    opMateConnector(context, makeId("cSys"), { "coordSystem" : coordSystem(vector(0, 0, 0) * meter, vector(1, 0, 0), vector(0, 0, 1)) });
    tag(context, makeId("tag"), { "tagPurpose" : TagPurpose.FORM, "positivePart" : qCreatedBy(makeId("positive"), EntityType.BODY),
                                  "negativePart" : qNothing(), "flatFormSketch" : {} as FeatureList,
                                  "cSysMateConnector" : qCreatedBy(makeId("cSys"), EntityType.BODY) });
    return context;
};

// A form tool: a cup, the boss above with a 4 mm hole up into it from below the sheet.
const cupTool = function(configuration is map) returns Context
{
    const context = newContextWithDefaults();
    const thickness = configuration.thickness == undefined ? 2 * millimeter : configuration.thickness;
    fCylinder(context, makeId("positive"), { "bottomCenter" : vector(0, 0, 0) * meter - vector(0, 0, 1) * thickness,
                                             "topCenter" : vector(0, 0, 2) * millimeter, "radius" : 5 * millimeter });
    fCylinder(context, makeId("negative"), { "bottomCenter" : vector(0, 0, -1) * millimeter - vector(0, 0, 1) * thickness,
                                             "topCenter" : vector(0, 0, 1) * millimeter, "radius" : 4 * millimeter });
    opMateConnector(context, makeId("cSys"), { "coordSystem" : coordSystem(vector(0, 0, 0) * meter, vector(1, 0, 0), vector(0, 0, 1)) });
    tag(context, makeId("tag"), { "tagPurpose" : TagPurpose.FORM, "positivePart" : qCreatedBy(makeId("positive"), EntityType.BODY),
                                  "negativePart" : qCreatedBy(makeId("negative"), EntityType.BODY), "flatFormSketch" : {} as FeatureList,
                                  "cSysMateConnector" : qCreatedBy(makeId("cSys"), EntityType.BODY) });
    return context;
};

function formOf(build is function) returns PartStudioData
{
    return { "buildFunction" : build, "configuration" : {}, "partQuery" : qEverything(EntityType.BODY) } as PartStudioData;
}

// sheet-metal-pattern: a boss formed on a plate, its faces patterned 3 times, 15 mm apart
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(60, 40) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    const pts = newSketchOnPlane(context, id + "pts", { "sketchPlane" : plane(vector(0, 0, 2) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skPoint(pts, "p1", { "position" : vector(12, 20) * millimeter });
    skSolve(pts);
    sheetMetalFormed(context, id + "form1", { "formPartStudio" : formOf(bossTool), "locations" : qOwnedByBody(qBodyType(qCreatedBy(id + "pts", EntityType.BODY), BodyType.POINT), EntityType.VERTEX), "flipDirection" : false, "targetFaces" : qClosestTo(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(30, 20, 2) * millimeter) });
    const dirX = newSketchOnPlane(context, id + "dirX", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(dirX, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(dirX);
    linearPattern(context, id + "pattern1", { "patternType" : PatternType.FACE, "faces" : qCreatedBy(id + "form1", EntityType.FACE), "directionOne" : qCreatedBy(id + "dirX", EntityType.EDGE), "distance" : 15 * millimeter, "instanceCount" : 3, "oppositeDirection" : false });
    return { "counts" : bodyCounts(context) };
}

// sheet-metal-pattern: a cup formed on a plate, its faces patterned 3 times round the plate's middle
export function c002(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(60, 40) * millimeter });
    skSolve(s1);
    sheetMetalStart(context, id + "sm1", { "thickness" : 2 * millimeter, "oppositeDirection" : false, "radius" : 1 * millimeter, "flipDirectionUp" : false, "process" : SMProcessType.THICKEN, "regions" : qSketchRegion(id + "s1"), "tangentPropagation" : false, "bends" : qNothing() });
    const pts = newSketchOnPlane(context, id + "pts", { "sketchPlane" : plane(vector(0, 0, 2) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skPoint(pts, "p1", { "position" : vector(45, 20) * millimeter });
    skSolve(pts);
    sheetMetalFormed(context, id + "form1", { "formPartStudio" : formOf(cupTool), "locations" : qOwnedByBody(qBodyType(qCreatedBy(id + "pts", EntityType.BODY), BodyType.POINT), EntityType.VERTEX), "flipDirection" : false, "targetFaces" : qClosestTo(qOwnedByBody(qBodyType(qCreatedBy(id + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(30, 20, 2) * millimeter) });
    const axis1 = newSketchOnPlane(context, id + "axis1", { "sketchPlane" : plane(vector(30, 20, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis1, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skSolve(axis1);
    circularPattern(context, id + "pattern1", { "patternType" : PatternType.FACE, "faces" : qCreatedBy(id + "form1", EntityType.FACE), "axis" : qCreatedBy(id + "axis1", EntityType.EDGE), "angle" : 360 * degree, "instanceCount" : 3, "equalSpace" : true });
    return { "counts" : bodyCounts(context) };
}
